  --destructive: #9f3a2a;
  --border: var(--ink-border);
  --input: var(--input-wash);
  --ring: var(--festival-yellow);
  --chart-1: var(--ink);
  --chart-2: var(--ink-muted);
  --chart-3: var(--festival-yellow);
  --chart-4: var(--paper-muted);
  --chart-5: var(--input-wash);
  --radius: 0.35rem;
  --sidebar: var(--paper-card);
  --sidebar-foreground: var(--ink);
  --sidebar-primary: var(--ink);
  --sidebar-primary-foreground: var(--paper);
  --sidebar-accent: var(--paper-muted);
  --sidebar-accent-foreground: var(--ink);
  --sidebar-border: var(--ink-border);
  --sidebar-ring: var(--festival-yellow);
  --elevation-paper: 0 1px 2px rgb(23 23 23 / 0.06);
  --elevation-editorial: 1.5px 1.5px 0 0 var(--ink-border);
  --scrollbar-track: color-mix(in srgb, var(--muted) 72%, var(--background));
  --scrollbar-thumb: color-mix(in srgb, var(--muted-foreground) 42%, var(--border));
  --scrollbar-thumb-hover: color-mix(in srgb, var(--accent) 45%, var(--muted-foreground));
}

