  --sidebar-primary-foreground: var(--ink);
  --sidebar-accent: #2c2923;
  --sidebar-accent-foreground: var(--paper);
  --sidebar-border: #f7f3ea;
  --sidebar-ring: var(--festival-yellow);
  --elevation-paper: 0 1px 2px rgb(0 0 0 / 0.28);
  --elevation-editorial: 1.5px 1.5px 0 0 var(--paper);
  --scrollbar-track: color-mix(in srgb, var(--muted) 85%, var(--background));
  --scrollbar-thumb: color-mix(in srgb, var(--muted-foreground) 38%, var(--border));
  --scrollbar-thumb-hover: color-mix(in srgb, var(--accent) 55%, var(--muted-foreground));
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }

  html {
    @apply font-sans;
    scrollbar-gutter: stable;
    scrollbar-width: thin;
    scrollbar-color: var(--scrollbar-thumb) var(--scrollbar-track);
  }

  body {
    @apply bg-background text-foreground antialiased;
    line-height: 1.65;
  }

  h1,
  h2,
  h3 {
    font-family: var(--font-display);
    font-weight: 400;
    letter-spacing: -0.02em;
    line-height: 1.15;
